Explore the top 1000 greatest albums across music history in an immersive visual vinyl archive.

albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

// Helper to pull the primary genre for grouping and coloring
cleanData = albums.map(d =&gt; ({
  ...d,
  primary_genre: d.genres ? d.genres.split(",")[0].trim() : "other",
  decade: `${Math.floor(d.year / 10) * 10}s`
}))

// State for currently playing album on the turntable
mutable nowPlaying = cleanData[0]























// Turntable Deck component with integrated tab navigation
html`
&lt;div class="turntable-deck" id="turntable"&gt;
  &lt;div class="platter-area"&gt;
    &lt;div class="vinyl-record"&gt;
      &lt;div class="vinyl-label"&gt;
        &lt;img src="${nowPlaying.image_url}" alt="${nowPlaying.album}" /&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="deck-info"&gt;
    &lt;div class="deck-nav-bar"&gt;
      &lt;span style="font-size: 0.75rem; font-weight: 700; color: #ffd166; text-transform: uppercase;"&gt;VAULT TABS:&lt;/span&gt;
      &lt;a href="index.qmd" class="deck-nav-pill active"&gt;🎵 Turntable Wall&lt;/a&gt;
      &lt;a href="compare.qmd" class="deck-nav-pill"&gt;⚖️ Cover Compare ↗&lt;/a&gt;
      &lt;a href="game.qmd" class="deck-nav-pill"&gt;🎮 Higher / Lower Game ↗&lt;/a&gt;
      &lt;a href="about.qmd" class="deck-nav-pill"&gt;ℹ️ About ↗&lt;/a&gt;
    &lt;/div&gt;

    &lt;div style="font-size: 0.72rem; letter-spacing: 2px; color: #00f2fe; text-transform: uppercase; font-weight: 700;"&gt;
      ⚡ Active Turntable Platter
    &lt;/div&gt;
    &lt;h2 style="margin: 0.2rem 0 0.1rem 0; font-size: 1.75rem; font-weight: 800; color: #fff; line-height: 1.2;"&gt;
      ${nowPlaying.album}
    &lt;/h2&gt;
    &lt;div style="font-size: 1.05rem; color: #cbd5e1;"&gt;
      ${nowPlaying.artist} &lt;span style="color: #ffd166;"&gt;(${nowPlaying.year})&lt;/span&gt;
    &lt;/div&gt;
    &lt;div style="margin-top: 0.4rem; font-size: 0.85rem; color: #94a3b8;"&gt;
      Rank: &lt;strong style="color: #00f2fe;"&gt;#${nowPlaying.rank}&lt;/strong&gt; of 1000 &nbsp;|&nbsp;
      Rating: &lt;strong style="color: #ffd166;"&gt;⭐ ${nowPlaying.rating.toFixed(2)}&lt;/strong&gt; &nbsp;|&nbsp;
      Genre: &lt;strong style="color: #e2e8f0; text-transform: capitalize;"&gt;${nowPlaying.primary_genre}&lt;/strong&gt;
    &lt;/div&gt;

    &lt;div class="equalizer-wrap"&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
      &lt;div class="eq-bar"&gt;&lt;/div&gt;
    &lt;/div&gt;

    &lt;div class="deck-controls"&gt;
      &lt;button class="btn-neon" onclick=${() =&gt; {
