viewof search = Inputs.search(cleanData, {
  placeholder: "Search artist, album, genre, or release year..."
})









genresList = ["All", "rock", "pop", "folk", "electronica", "punk", "hip-hop", "soul", "jazz", "country", "metal"]
viewof genreFilter = Inputs.select(genresList, {
  label: "Genre",
  value: "All"
})


















viewof mosaicLimit = Inputs.select([72, 144, 300, 1000], {
  label: "Covers",
  value: 144
})









// Filter data by active search & genre
filtered = search.filter(d =&gt; genreFilter === "All" || d.primary_genre === genreFilter)







md`### Visual Cover Mosaic (*${Math.min(mosaicLimit, filtered.length)} of ${filtered.length} matching covers — click any to play on turntable*)`







// Pure visual mosaic of album covers without any bottom card list
html`&lt;div class="mosaic-wall"&gt;
  ${filtered.slice(0, mosaicLimit).map(d =&gt; html`
    &lt;div class="mosaic-tile" title="#${d.rank}: ${d.album} - ${d.artist} (${d.year}) | ⭐ ${d.rating.toFixed(2)}" onclick=${() =&gt; {
      mutable nowPlaying = d;
      document.getElementById('turntable').scrollIntoView({ behavior: 'smooth' });
    }}&gt;
      &lt;img src="${d.image_url}" alt="${d.album}" loading="lazy" /&gt;
      &lt;span class="mosaic-rank"&gt;#${d.rank}&lt;/span&gt;
    &lt;/div&gt;
  `)}
&lt;/div&gt;`

Test your musical knowledge! Guess whether the mystery album is ranked HIGHER or LOWER in the all-time top 1000 list.

albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

cleanAlbums = albums.map(d =&gt; ({
  ...d,
  primary_genre: d.genres ? d.genres.split(",")[0].trim() : "other"
}))

// Game State: current streak, best streak, round, albumA, albumB, status
mutable currentStreak = 0
mutable bestStreak = 0
mutable gameStatus = "playing" // "playing", "won", "lost"
mutable roundCounter = 1

// Random seed triggers
function getRandomAlbum(excludeRank) {
  let item = cleanAlbums[Math.floor(Math.random() * cleanAlbums.length)];
  while (excludeRank && item.rank === excludeRank) {
    item = cleanAlbums[Math.floor(Math.random() * cleanAlbums.length)];
  }
  return item;
}

mutable gameAlbumA = cleanAlbums[Math.floor(Math.random() * 200)]
mutable gameAlbumB = getRandomAlbum(gameAlbumA.rank)

































































// Integrated navigation header
html`
&lt;div class="turntable-deck" style="padding: 1rem 1.5rem; margin-bottom: 1.5rem; grid-template-columns: 1fr;"&gt;
  &lt;div class="deck-nav-bar" style="margin-bottom: 0; padding-bottom: 0; border-bottom: none;"&gt;
    &lt;span style="font-size: 0.75rem; font-weight: 700; color: #ffd166; text-transform: uppercase;"&gt;VAULT TABS:&lt;/span&gt;
